func TestExportGatewayContract(t *testing.T){dir:=os.Getenv("CONTRACT_FIXTURE_DIR");if dir==""{return};b:=AttemptBinding{RequestID:"11111111-1111-4111-8111-111111111111",AttemptID:"22222222-2222-4222-8222-222222222222",Operation:"application.question",ObjectKind:"application",ObjectCode:"app",EnvCode:"rdev.ali",SkillsCommit:strings.Repeat("a",40),Model:"gpt-5.6-luna"};r:=validLiveResult(b);stamp:=time.Date(2026,10,7,0,0,0,0,time.UTC);r.GeneratedAt=stamp;for i:=range r.Evidence{r.Evidence[i].ObservedAt=stamp};r.Usage=[]Usage{{Input:100,Output:20,TotalTokens:120}};x:=Execution{RequestID:b.RequestID,AttemptID:b.AttemptID,Status:"completed",RuntimeMode:"live",Result:&r,CheckpointStatus:"verified",CleanupStatus:json.RawMessage(`{"sandboxAbsent":true,"keyAbsent":true,"accessRevoked":true}`),Cleanup:"confirmed",UpdatedAt:stamp};raw,e:=json.MarshalIndent(x,"","  ");if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(dir,"gateway-execution.json"),append(raw,'\n'),0644);e!=nil{t.Fatal(e)}}
